    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("첫 열매를 보다", "오 알라, 우리의 열매를 축복하시고, 우리 도시에서 우리를 축복하시고, 우리의 사'와 진흙(측정)에서도 우리를 축복하소서.", "계절의 첫 열매를 보았을 때.", "공급과 도시의 축복을 위한 이중입니다."),
        "dua_good_news" to DuaText("기쁜 소식이 있을 때", "모든 찬양은 알라에게 있으며, 알라의 호의로 좋은 일이 완성됩니다.", "좋은 소식을 듣고 (감사의 절을 합니다.)", "예언자 ﷺ은 자신이 좋아하는 것을 보고 이렇게 말했습니다."),
        "dua_looking_mirror" to DuaText("거울을 보면서", "오 알라시여, 당신께서 제 외모를 좋게 하신 것처럼 제 성격도 좋게 만들어 주십시오.", "거울을 볼 때.", "예언자 ﷺ은 이 두아를 만들었습니다(거울에 대한 언급 없이도 확립되었습니다)."),
        "dua_rabbana_taqabbal" to DuaText("증서의 수락", "우리 주님, 이것을 우리에게서 받아 주십시오. 참으로 당신은 모든 것을 들으시고 모든 것을 아시는 분이십니다. 그리고 우리의 회개를 받아들이십시오. 참으로 당신은 회개를 받아들이시는 분이시며 자비로우신 분이십니다.", "Ka'bah를 건설하는 동안 Ibrahim과 Isma'il (AS)이 질문했습니다.", "모든 선행 후에는 수락에 대한 이중입니다."),
        "dua_muawwidhat" to DuaText("세 가지 Quls (Mu'awwidhat)", "(Surah al-Ikhlas) 말하세요: 그는 알라, 유일한 분이십니다. 알라, 자급자족하시는 분. 그는 낳지도 태어나지도 않습니다. 그리고 그분과 비교할 만한 사람은 없습니다.\n\n(알 팔라크 수라) 말하라: 나는 새벽의 주님 안에서, 그분이 창조하신 악에서, 어둠이 가라앉을 때의 악에서, 매듭을 짓는 자들의 악에서, 질투하는 자들의 악에서 피난처를 구합니다.\n\n(Surah an-Nas) 말하십시오 : 나는 진과 인류 사이에서 인류의 마음에 속삭이는 후퇴하는 속삭이는 사람의 악으로부터 인류의 주님, 인류의 왕, 인류의 신에게 피난처를 구합니다.", "세 수라를 아침저녁으로 세 번씩, 잠들기 전 손에 입김을 불어넣고 몸 전체를 닦아냅니다.", "아침저녁으로 세 번씩 외우면 모든 일에 충분합니다."),
        "dua_sabr" to DuaText("인내와 확고함을 위해", "우리 주님, 우리에게 인내를 부어주시고, 우리의 발을 굳건하게 하시고, 믿지 않는 사람들에 맞서 우리를 도우소서.", "고난과 대결의 시대에.", "탈루트 군대의 듀아."),
        "dua_rabbana_innana_amanna" to DuaText("용서와 화재로부터의 보호", "주님, 저희가 믿었으니 저희 죄를 용서하시고 불의 형벌에서 저희를 지켜 주소서.", "꾸란 두아.", "하나님을 경외하는 자의 자질 중에 언급되는 두아."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("우리 일에 대한 지침(Ashab al-Kahf)", "우리 주님, 우리에게 당신의 자비를 베풀어 주시고 우리가 하는 일에 있어서 올바른 인도를 마련해 주십시오.", "동굴 사람들의 두아.", "결정과 어려운 상황에 대한 지침."),
        "dua_musa_faqir" to DuaText("공급을 위한 무사 (AS)의 두아", "나의 주님, 당신이 나에게 보내주시는 어떤 좋은 것이든지 나는 참으로 필요합니다.", "공급과 선을 추구합니다 — Madyan에 있는 Musa (AS)의 이중입니다.", "이 이중 후에 알라는 무사 (AS)에게 집과 직장, 아내를 부여했습니다."),
        "dua_ayyub" to DuaText("질병에 걸린 Ayyub (AS)의 Dua", "(나의 주님,) 해가 저에게 닿았으며 당신은 자비로운 자 중에서 가장 자비로운 분이십니다.", "질병과 고통 속에서.", "알라는 Ayyub (AS)의 고통을 제거했습니다."),
        "dua_husn_khatimah" to DuaText("무슬림으로 죽다(Yusuf AS)", "하늘과 땅의 창조주여, 당신은 이 세상과 내세에서 나의 보호자이십니다. 나를 무슬림으로 죽게 하시고 의로운 자들과 함께하게 하소서.", "좋은 결말을 위한 듀아.", "예언자 유수프 (AS)의 두아."),
        "dua_shaitan_hamazat" to DuaText("악마의 속삭임으로부터 피난처", "나의 주님, 나는 마귀들의 속삭임으로부터 당신께 피난처를 구하며, 그들이 나에게 가까이 오지 않도록 나의 주님 당신께 피난처를 구합니다.", "사탄의 속삭임을 피하십시오.", "피난처를 찾는 꾸란 듀아."),
        "dua_bad_character" to DuaText("나쁜 성격으로부터 피난처", "오 알라, 나는 나쁜 성격, 나쁜 행동, 악한 욕망으로부터 당신께 피난처를 구합니다.", "나쁜 성격, 행동, 욕망을 피하십시오.", "선지자 ﷺ의 피난처 이중."),
        "dua_zawal_nimah" to DuaText("축복의 상실로부터 피난처", "오 알라, 나는 당신의 축복의 상실, 당신이 주신 행복의 변화, 당신의 갑작스런 형벌과 당신의 모든 불만으로부터 피난처를 구합니다.", "축복을 잃고 갑작스러운 재난을 피하십시오.", "예언자 ﷺ의 이중곡."),
        "dua_useless_knowledge" to DuaText("유익하지 않은 지식으로부터 피난처", "오 알라, 나는 유익하지 못한 지식, 두려워하지 않는 마음, 결코 만족하지 못하는 영혼, 응답되지 않는 이중에서 당신께 피난처를 구합니다.", "쓸모없는 지식과 알라를 두려워하지 않는 마음을 피하십시오.", "선지자 ﷺ의 피난처 이중."),
        "dua_beneficial_knowledge" to DuaText("유익한 지식 & 할랄 리즈크", "오 알라, 나는 당신에게 유익한 지식과 순수한 양식과 받아들인 행위를 간구합니다.", "파즈르 기도 후.", "예언자 ﷺ은 파즈르의 살람 후에 이렇게 말했습니다."),
        "dua_leprosy_diseases" to DuaText("심각한 질병으로부터의 피난처", "오 알라, 나는 백반증, 광기, 나병 및 모든 사악한 질병으로부터 당신께 피난처를 구합니다.", "심각한 질병으로부터 보호합니다.", "건강 보존을 위한 Sunnah dua."),
        "dua_fear_people" to DuaText("적이나 압제자에 대한 두려움", "오 알라, 우리는 당신을 그들 앞에 두고 그들의 악으로부터 당신께 피난처를 구합니다.", "사람이나 사람의 해를 두려워할 때.", "선지자 ﷺ은 백성을 두려워했을 때 이렇게 말했습니다."),
        "dua_shirk_protection" to DuaText("숨겨진 회피로부터의 보호", "오 알라, 나는 고의로 당신과 어떤 것도 연관시키지 않도록 당신께 피난처를 구하며, 내가 모르고 행한 일에 대해 당신의 용서를 구합니다.", "과시하고 숨는 회피로부터 안전을 유지합니다.", "숨겨진 회피는 개미가 기어다니는 것보다 더 숨겨져 있습니다."),
        "dua_rain" to DuaText("비가 올 때", "오 알라여, 유익한 비를 보내소서.", "비가 올 때.", "비는 듀아를 받아들이는 시간이다."),
        "dua_after_rain" to DuaText("비가 내린 후", "우리는 알라의 은총과 자비로 인해 비를 받았습니다.", "비가 내린 후.", "이렇게 말하는 사람은 알라를 믿는 사람입니다."),
        "dua_istisqa" to DuaText("비를 청하며(Istisqa)", "오 알라여, 우리에게 비를 보내소서(세 번).", "비가 없을 때.", "선지자 ﷺ이 금요일 설교에서 이 두아를 만들었고 비가 내렸습니다."),
        "dua_heavy_rain" to DuaText("과도한 비", "오 알라, (그것이 떨어지게 해주세요) 우리 주변이 아니라 우리 위에 있게 하소서.", "비가 너무 많이 올 때.", "구름은 예언자 ﷺ의 두아를 통해 멀어졌습니다."),
        "dua_wind" to DuaText("바람이 불 때", "오 알라, 나는 당신에게 그것의 좋은 것과 그것 안에 있는 좋은 것과 그것과 함께 보내진 것의 좋은 것을 구하며 그것의 악과 그것 안에 있는 악과 그것과 함께 보내진 것의 악으로부터 당신께 피난처를 구합니다.", "강한 바람이나 폭풍이 불 때.", "예언자 ﷺ은 폭풍이 몰아칠 때 이 듀아를 만들었습니다."),
        "dua_thunder" to DuaText("천둥소리 듣기", "천둥이 찬양으로 영광을 돌리는 분에게 영광을 돌리고 천사들도 그를 두려워합니다.", "천둥 소리를 들었을 때 - Abdullah ibn az-Zubayr (RA)의 실천.", "Surah ar-Ra'd(13:13)에서 가져옴."),
        "dua_new_moon" to DuaText("초승달 보기", "오 알라, 이 달이 축복과 믿음, 안전과 이슬람으로 우리 위에 떠오르게 하소서. (오 달이여) 나의 주님, 당신의 주님은 알라이십니다.", "초승달을 보면서.", "매 달마다 Sunnah dua가 제공됩니다."),
        "dua_janaza_adult" to DuaText("자나자 기도(성인)", "오 알라, 우리의 산 자와 죽은 자, 현존하는 자와 부재한 자, 우리의 젊은이와 노인, 우리의 남자와 여자를 용서하소서. 오 알라, 당신이 우리 중 누구든지 이슬람에 따라 살려주시고, 우리 중 누구든지 당신이 죽게 하는 자는 믿음으로 죽게 하소서.", "장례기도의 세 번째 탁비르 이후.", "사망한 성인을 위한 Sunnah dua입니다."),
        "dua_janaza_child" to DuaText("자나자 기도(어린이)", "오 알라시여, 그를 우리의 선구자(그리고 주인)로 삼으시고, 그를 우리에게 보상과 보물로 삼으시고, 우리의 중보가 받아들여지는 중보자가 되게 하소서.", "어린이의 장례 기도에서(소녀의 경우 'ij'alhā'라고 말함)", "Hanafis가 수행하는 Sunnah dua."),
        "dua_mayyit_awf" to DuaText("고인을 위한 상세한 두아", "오 알라여, 그를 용서하시고, 그에게 자비를 베푸시며, 그에게 안녕을 주시고, 용서해 주십시오. 그의 영접을 영화롭게 하시고 그의 무덤을 넓게 하시고 물과 눈과 우박으로 그를 씻으시고 흰 옷이 더러움을 씻어 주듯이 그를 죄에서 깨끗하게 하소서.", "장례 기도나 고인을 위한 기도에서.", "Awf ibn Malik (RA)은 자신이 죽은 사람이기를 바랐습니다."),
        "dua_visiting_graves" to DuaText("무덤 방문", "이 집에 거주하는 믿는 무슬림 주민 여러분, 평화가 있기를 바랍니다. 알라께서 원하신다면 우리도 당신과 합류할 것입니다. 나는 알라에게 우리와 당신의 안녕을 간구합니다.", "묘지에 들어갈 때.", "무덤을 방문하는 것은 죽음과 내세를 생각나게 합니다."),
        "dua_closing_eyes" to DuaText("고인의 눈을 감으면", "오 알라여, (이름)을 용서하시고, 인도받는 자들 사이에서 그의 지위를 높이고, 그가 뒤에 남겨둔 자들 중에서 그의 후계자가 되어 주십시오. 오 세상의 주님이시여, 우리와 그를 용서해 주십시오. 그의 무덤을 넓게 하고 빛으로 채우라.", "고인의 눈을 감을 때(그의 이름을 언급함)", "예언자 ﷺ은 아부 살라마 (RA)을 위해 이 듀아를 만들었습니다."),
        "dua_condolence" to DuaText("애도(Ta'ziyah)", "그가 취한 것은 분명히 알라의 것이고 그가 준 것도 그에게 속하며 그와 관련된 모든 것은 정해진 기간이 있으니 인내하고 보상을 바라라.", "사망 후 가족에게 조의를 표합니다.", "예언자 ﷺ은 이 메시지를 그의 딸에게 보냈습니다."),
        "dua_placing_in_grave" to DuaText("고인을 무덤에 장사함", "알라의 이름으로 그리고 알라의 메신저의 길로 ﷺ.", "고인을 무덤으로 내릴 때.", "Sunnah 매장의 dua."),
        "dua_sneezing" to DuaText("재채기", "모든 찬양은 알라를 위한 것입니다. — 알라께서 당신에게 자비를 베푸시기를 바랍니다. — 알라께서 당신을 인도하시고 당신의 일을 바로잡으시길 바랍니다.", "재채기할 때; 듣는 사람이 'Yarhamukallah'라고 말하면 재채기를 한 사람이 대답합니다.", "그것은 다른 무슬림에 대한 무슬림의 권리 중 하나입니다."),
        "dua_toilet_enter" to DuaText("화장실에 들어가기", "알라의 이름으로. 오 알라, 나는 남성과 여성의 불순한 진으로부터 당신께 피난처를 구합니다.", "왼발로 화장실에 들어가기 전.", "Bismillah는 진과 사람 사이의 스크린이 됩니다."),
        "dua_toilet_exit" to DuaText("화장실에서 나가기", "(오 알라) 나는 당신의 용서를 구합니다.", "오른발로 화장실에서 나올 때.", "선지자 ﷺ은 화장실을 떠날 때 이렇게 말했습니다."),
        "dua_thanking" to DuaText("누군가에게 감사하기", "알라께서 당신에게 선한 보상을 해주시기를 바랍니다.", "누군가가 당신에게 호의를 베풀 때.", "이렇게 말하는 사람은 감사의 뜻을 충분히 표현한 것입니다."),
        "dua_love_for_allah" to DuaText("누군가가 '알라를 위해 당신을 사랑합니다'라고 말할 때", "당신이 나를 사랑하는 그분(알라)이 당신을 사랑하기를 바랍니다.", "누군가가 '나는 알라를 위해 당신을 사랑합니다'라고 말할 때.", "Sunnah는 알라를 위한 사랑에 응답합니다."),
        "dua_seeing_muslim_smile" to DuaText("인사말(살람)", "당신에게 평화가 있기를, 알라의 자비와 그분의 축복이 있기를 바랍니다.", "무슬림을 만날 때.", "완전한 살람을 말하면 삼십 선행을 얻게 됩니다."),
